edits.new:
function createLegend(sectorColors) {
    const legend = d3.select('#legend');
    let sectors = [...new Set(stocksData.map(d => d.sector))];
    // Ensure required sectors are present in legend
    const requiredSectors = ['energy', 'financial', 'industry', 'information technology', 'etf'];
    requiredSectors.forEach(s => {
        if (!sectors.includes(s)) sectors.push(s);
    });

    sectors.forEach(sector => {
        const item = legend.append('div').attr('class', 'legend-item');
        item.append('span').attr('class', 'legend-color')
            .style('background-color', sectorColors[sector] || '#ccc');
        item.append('span').attr('class', 'legend-label').text(sector);
    });
}

