    selectedTicker = ticker;
    circles.attr('stroke', d => d.ticker === ticker ? '#000' : '#333')
           .attr('stroke-width', d => d.ticker === ticker ? 3 : 1);

    // Explicitly iterate rows to ensure class toggling works reliably for Playwright
    d3.selectAll('#stock-table tbody tr').each(function(d) {
        d3.select(this).classed('highlighted', d.ticker === ticker);
    });
};

